export const L23_QUIZ = {
  id: 'L2.3-microbiology-parasitology',
  title: 'L2.3 · Vi sinh — Ký sinh trùng',
  kind: 'quiz',
  yearLevel: 2, subject: 'vi-sinh', difficulty: 2,
  skillsTrained: ['gram-staining', 'antibiotic-susceptibility', 'parasitology'],
  questions: [
    { stem: 'Vi khuẩn Gram dương (G+) khi nhuộm Gram sẽ bắt màu gì?', choices: ['Đỏ hồng (do safranin)', 'Tím (do crystal violet–iod giữ lại trong vách tế bào dày peptidoglycan)', 'Vàng', 'Xanh'], answer: 1, explanation: 'Quy trình Gram: crystal violet → iod (mordant) → cồn (rửa) → safranin. Vi khuẩn G+ có vách peptidoglycan dày (20-80 nm), giữ lại phức crystal violet-iod khi rửa cồn → tím. G- vách mỏng và có lớp lipid ngoài (LPS) → cồn rửa trôi tím → bắt safranin → đỏ hồng.' },
    { stem: 'Trong các vi khuẩn sau, vi khuẩn nào là Gram âm?', choices: ['Staphylococcus aureus', 'Streptococcus pneumoniae', 'Escherichia coli', 'Enterococcus faecalis'], answer: 2, explanation: 'E. coli (trực khuẩn Gram âm, thuộc Enterobacteriaceae). S. aureus và S. pneumoniae là cầu khuẩn Gram dương. Enterococcus faecalis cũng là cầu khuẩn G+. Việc phân biệt G+/G- quan trọng để chọn kháng sinh phổ.' },
    { stem: 'Phương pháp kháng sinh đồ Kirby-Bauer (đĩa giấy khuếch tán) đánh giá độ nhạy bằng:', choices: ['Đo nồng độ vi khuẩn trong máu', 'Đo đường kính vòng vô khuẩn quanh đĩa kháng sinh và so với bảng chuẩn CLSI/EUCAST', 'Quan sát màu môi trường', 'Đếm khuẩn lạc'], answer: 1, explanation: 'Kirby-Bauer: cấy vi khuẩn lên đĩa Mueller-Hinton, đặt đĩa giấy tẩm kháng sinh, ủ 35°C/16-18h. Đo đường kính vòng vô khuẩn (mm) → tra bảng CLSI/EUCAST → phân loại S (sensitive/nhạy), I (intermediate), R (resistant/kháng). Là phương pháp định tính, thay thế bằng MIC (định lượng) cho mẫu nhiễm trùng nặng.' },
    { stem: 'Penicillin tác động lên cấu trúc nào của vi khuẩn?', choices: ['Ribosome', 'Vách tế bào (ức chế PBP — transpeptidase tổng hợp peptidoglycan)', 'ADN gyrase', 'Màng tế bào'], answer: 1, explanation: 'Beta-lactam (penicillin, cephalosporin, carbapenem) gắn vào penicillin-binding protein (PBP) → ức chế cross-linking peptidoglycan → vách tế bào yếu → vi khuẩn ly giải khi áp suất thẩm thấu. Hiệu quả mạnh trên G+ (vách dày peptidoglycan). G- cần beta-lactam thấm qua LPS (vd: ampicillin, cefotaxim).' },
    { stem: 'Giun đũa (Ascaris lumbricoides) lây qua đường nào?', choices: ['Da', 'Đường tiêu hoá (nuốt trứng giun có trong rau sống, nước nhiễm)', 'Đường hô hấp', 'Đường máu'], answer: 1, explanation: 'Ascaris lây qua nuốt trứng có ấu trùng giai đoạn 2 → trứng nở ở ruột non → ấu trùng xuyên thành ruột → tuần hoàn → phổi → lên hầu họng → nuốt xuống ruột → giun trưởng thành. Thuốc: albendazol/mebendazol 400mg liều duy nhất. Nguồn lây: rau sống, nước nhiễm phân tươi.' },
    { stem: 'Sán dây bò (Taenia saginata) lây sang người qua:', choices: ['Đốt muỗi', 'Ăn thịt bò tái/sống chứa nang ấu trùng cysticercus', 'Hít phải', 'Uống nước nhiễm'], answer: 1, explanation: 'Chu kỳ T. saginata: trứng/đốt → phân người → bò ăn cỏ nhiễm → ấu trùng đi đến cơ → nang cysticercus → người ăn thịt bò tái → sán trưởng thành dài 4-12 m trong ruột. Thuốc: praziquantel 5-10 mg/kg liều duy nhất hoặc niclosamid 2g.' },
    { stem: 'Vi khuẩn Mycobacterium tuberculosis (lao) không bắt màu Gram thông thường, phải nhuộm bằng:', choices: ['Giemsa', 'Ziehl-Neelsen (carbol fuchsin — phương pháp nhuộm kháng acid AFB)', 'Methylene blue', 'PAS'], answer: 1, explanation: 'M. tuberculosis có thành tế bào nhiều acid mycolic → không bắt Gram thường. Nhuộm Ziehl-Neelsen: carbol fuchsin nóng → tẩy bằng acid-alcohol → metylen xanh đối nhuộm. Vi khuẩn kháng acid (AFB) giữ màu đỏ trên nền xanh. Là xét nghiệm AFB đờm cơ bản chẩn đoán lao.' },
    { stem: 'Hiện tượng "đề kháng kháng sinh" (antibiotic resistance) có cơ chế phổ biến nào?', choices: ['Vi khuẩn tự chết', 'Sản xuất enzyme phá huỷ kháng sinh (vd β-lactamase), bơm đẩy ra (efflux pump), thay đổi đích (mutated PBP), giảm tính thấm', 'Vi khuẩn ngừng phân chia', 'Vi khuẩn đổi màu'], answer: 1, explanation: '4 cơ chế kháng kháng sinh chính: (1) Phá huỷ thuốc (β-lactamase, ESBL, carbapenemase); (2) Bơm đẩy thuốc ra (efflux); (3) Thay đổi đích tác dụng (PBP biến đổi → MRSA; gyrase mutation → kháng quinolon); (4) Giảm tính thấm màng. Kết quả: vi khuẩn sống sót dù có kháng sinh.' },
    { stem: 'Vi khuẩn Helicobacter pylori (gây viêm loét dạ dày) là:', choices: ['Cầu khuẩn Gram dương', 'Trực khuẩn xoắn Gram âm, tạo urease phân huỷ urê tạo môi trường base bảo vệ trong acid dạ dày', 'Virus', 'Nấm'], answer: 1, explanation: 'H. pylori = trực khuẩn xoắn G-, microaerophilic. Tiết urease: urê → NH3 + CO2 (NH3 trung hoà HCl quanh vi khuẩn) → sống trong dạ dày. Test urea breath, test nhanh urease (CLO test), kháng nguyên phân để chẩn đoán. Điều trị: phác đồ 3 thuốc (PPI + amoxicillin + clarithromycin) hoặc 4 thuốc có bismuth.' },
    { stem: 'Amíp Entamoeba histolytica gây bệnh lỵ amíp, lây truyền qua:', choices: ['Đường muỗi đốt', 'Đường tiêu hoá (nuốt bào nang amíp trong nước/thức ăn nhiễm phân)', 'Đường tình dục', 'Đường hô hấp'], answer: 1, explanation: 'E. histolytica có 2 dạng: thể bào nang (cyst) lây nhiễm qua nước/thức ăn nhiễm phân; thể hoạt động (trophozoite) gây loét đại tràng → đi cầu phân máu nhầy. Có thể di căn áp xe gan. Thuốc: metronidazol 750mg x 3 lần/ngày x 7-10 ngày + thuốc diệt nang (paromomycin, diloxanid).' },
  ],
};

export const L24_QUIZ = {
  id: 'L2.4-enzyme-kinetics-quiz',
  title: 'L2.4 · Sinh hoá — Enzyme kinetics',
  kind: 'quiz',
  yearLevel: 2, subject: 'sinh-hoa', difficulty: 2,
  skillsTrained: ['enzyme-kinetics', 'michaelis-menten', 'inhibition'],
  questions: [
    { stem: 'Hằng số Michaelis (Km) trong động học enzyme có ý nghĩa gì?', choices: ['Tốc độ phản ứng tối đa', 'Nồng độ cơ chất [S] khi v = ½ Vmax — phản ánh ái lực enzyme với cơ chất (Km thấp = ái lực cao)', 'Số phân tử cơ chất chuyển hoá/giây', 'Hằng số phân ly enzyme'], answer: 1, explanation: 'Phương trình Michaelis-Menten: v = Vmax·[S]/(Km + [S]). Khi [S] = Km → v = Vmax/2. Km thấp → enzyme ái lực cao với cơ chất (cần [S] thấp đã đạt nửa Vmax). Đơn vị Km giống đơn vị [S] (mol/L). Kcat = Vmax/[E]total = số phân tử/giây/enzyme.' },
    { stem: 'Đồ thị Lineweaver-Burk (1/v vs 1/[S]) cho:', choices: ['Đường cong hyperbol', 'Đường thẳng có hệ số góc = Km/Vmax, cắt tung độ tại 1/Vmax, cắt hoành tại -1/Km', 'Đường parabol', 'Đường sigmoid'], answer: 1, explanation: 'Nghịch đảo phương trình Michaelis-Menten: 1/v = (Km/Vmax)·(1/[S]) + 1/Vmax → đường thẳng y = mx + b với slope = Km/Vmax, intercept y = 1/Vmax, intercept x = -1/Km. Dễ tính Km, Vmax từ thực nghiệm dù sai số ở [S] thấp bị khuếch đại.' },
    { stem: 'Chất ức chế cạnh tranh (competitive inhibitor) ảnh hưởng đến Km và Vmax như thế nào?', choices: ['Km tăng (giảm ái lực biểu kiến), Vmax không đổi', 'Cả Km và Vmax đều giảm', 'Vmax giảm, Km không đổi', 'Không ảnh hưởng'], answer: 0, explanation: 'Ức chế cạnh tranh: chất ức chế và cơ chất cùng cạnh tranh ở activate site → Km biểu kiến TĂNG (cần [S] cao hơn để đạt nửa Vmax). Vmax KHÔNG đổi (nếu [S] đủ lớn vẫn đẩy hết chất ức chế ra). Trên Lineweaver-Burk: các đường thẳng giao nhau ở trục y (tại 1/Vmax).' },
    { stem: 'Ức chế không cạnh tranh (non-competitive inhibitor) khác với cạnh tranh ở điểm:', choices: ['Vmax giảm, Km không đổi (chất ức chế gắn vào allosteric site, không cạnh tranh với cơ chất)', 'Km giảm, Vmax tăng', 'Cả Km và Vmax đều tăng', 'Không khác gì'], answer: 0, explanation: 'Non-competitive: chất ức chế gắn allosteric site → enzyme-substrate vẫn tạo thành nhưng kém hoạt động → giảm số phân tử có chức năng → Vmax GIẢM, Km KHÔNG ĐỔI (ái lực cơ chất không thay đổi). Lineweaver-Burk: đường thẳng giao nhau ở trục x.' },
    { stem: 'Enzyme allosteric (vd phosphofructokinase trong glycolysis) có đồ thị động học hình:', choices: ['Đường thẳng', 'Đường cong sigmoid (chữ S) — do tính cộng tác (cooperativity) giữa các tiểu đơn vị', 'Hyperbol Michaelis-Menten cổ điển', 'Đường parabol'], answer: 1, explanation: 'Enzyme allosteric thường có nhiều tiểu đơn vị (subunits), khi 1 subunit gắn cơ chất → làm tăng ái lực các subunit khác (cooperativity dương) → đường cong sigmoid. Tương tự đường cong oxy-Hb. Hệ số Hill (n) > 1 cho cooperativity dương. Cho phép enzyme đáp ứng nhanh khi [S] vượt ngưỡng.' },
    { stem: 'Methotrexate (thuốc ung thư, miễn dịch) ức chế enzyme dihydrofolate reductase theo cơ chế:', choices: ['Ức chế cạnh tranh (tương tự cấu trúc acid folic, cạnh tranh với folate)', 'Ức chế allosteric', 'Phá huỷ enzyme', 'Không liên quan enzyme'], answer: 0, explanation: 'Methotrexate là chất tương tự cấu trúc acid folic (folate analog) → cạnh tranh tại active site của dihydrofolate reductase → ngăn tổng hợp tetrahydrofolate → ngăn tổng hợp purin/pyrimidin → ngừng tăng sinh tế bào. Đặc tính ức chế cạnh tranh → có thể "đảo" bằng tăng folate (leucovorin rescue).' },
    { stem: 'Đơn vị quốc tế (IU) của enzyme được định nghĩa là:', choices: ['Khối lượng enzyme tính bằng mg', 'Lượng enzyme xúc tác chuyển hoá 1 μmol cơ chất/phút ở điều kiện chuẩn', 'Số tiểu đơn vị enzyme', 'Hằng số Michaelis'], answer: 1, explanation: '1 IU (International Unit) = lượng enzyme xúc tác chuyển hoá 1 μmol cơ chất/phút (điều kiện chuẩn: nhiệt độ, pH, [S] tối ưu). Đơn vị mới hơn: katal (kat) = 1 mol/giây (1 IU ≈ 16,67 nkat). Hoạt tính riêng (specific activity) = IU/mg protein → đánh giá độ tinh khiết.' },
    { stem: 'Trong huyết thanh, hoạt tính enzyme nào tăng đặc hiệu khi tổn thương cơ tim?', choices: ['ALT (alanine aminotransferase)', 'Troponin I/T (không phải enzyme nhưng đặc hiệu cơ tim) và CK-MB (creatine kinase isoform MB)', 'Amylase', 'Lipase'], answer: 1, explanation: 'Tổn thương cơ tim → tăng troponin I/T (đặc hiệu nhất, marker chính), CK-MB (isoform tim của creatine kinase), AST/LDH (kém đặc hiệu). ALT tăng đặc hiệu trong tổn thương gan. Amylase/lipase đặc hiệu cho tuỵ.' },
    { stem: 'Khi nhiệt độ tăng dần từ 0°C → 60°C, hoạt tính enzyme nói chung sẽ:', choices: ['Luôn tăng tuyến tính theo nhiệt độ', 'Tăng dần đến nhiệt độ tối ưu (37°C ở enzyme người), sau đó GIẢM nhanh do enzyme bị biến tính (denaturation)', 'Luôn giảm', 'Không phụ thuộc nhiệt độ'], answer: 1, explanation: 'Theo quy tắc Q10 (Van\'t Hoff), tốc độ phản ứng tăng ~2 lần khi nhiệt độ tăng 10°C. Nhưng ở nhiệt độ vượt tối ưu (37°C cho người), cấu trúc 3D enzyme bị phá vỡ → mất hoạt tính (denaturation). Enzyme thermophilic (Taq polymerase) chịu được 95°C.' },
    { stem: 'Enzyme G6PD (glucose-6-phosphate dehydrogenase) trong RBC bị thiếu hụt sẽ:', choices: ['Không ảnh hưởng', 'Gây tan máu khi tiếp xúc một số thuốc oxy hoá (primaquin, sulfonamid, dapsone, đậu fava) — bệnh Favism', 'Tăng đông máu', 'Giảm hấp thu sắt'], answer: 1, explanation: 'G6PD deficiency là bệnh di truyền lặn liên kết X (phổ biến ở nam Địa Trung Hải, Đông Nam Á, châu Phi). G6PD cung cấp NADPH chống stress oxy hoá ở RBC. Thiếu → RBC dễ bị huỷ khi gặp tác nhân oxy hoá: primaquin (sốt rét), sulfonamid, dapsone, nitrofurantoin, đậu fava (bệnh Favism). Cần xét nghiệm G6PD trước khi kê primaquin chống sốt rét.' },
  ],
};

